-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "zhTW" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.priest.dps.Name"] = "傷害"
L["rm.era.priest.dps.Description"] = "1 至 60 級的傷害輸出，也是治療內建循環不適用時（單人、暗影或尚未取得天賦）牧師的預設循環。學會後使用暗影形態；拉怪前單人時先上護盾，然後是神聖之火（沒有暗影形態時）、心靈震爆或懲擊。對每個會存活較久的目標施放一次暗言術：痛，心靈震爆冷卻結束即使用，精神鞭笞作為填充（學會前用懲擊與神聖新星），單人時對瀕死目標或法力不足時使用魔杖。長時間戰鬥時使用吸血鬼的擁抱與噬靈瘟疫，團隊中絕不使用。提醒：心靈之火、真言術：韌、種族增益、搭配心靈震爆使用心靈專注、生命力剩一半且有兩個敵人接近你時使用心靈尖嘯、目標轉向你時使用漸隱術、絕望禱言。目標選擇、多目標持續傷害與降級施法由你自行處理。"
L["rm.era.priest.dps.simulator.Name"] = "傷害（模擬器 不死族團隊）"
L["rm.era.priest.dps.simulator.Description"] = "推薦的傷害優先順序，搭配 模擬器 為不死族牧師提供的團隊選擇：心靈專注用於噬靈瘟疫而非心靈震爆，團隊中也會施放噬靈瘟疫，因此只在你的團隊還有空餘減益效果欄位時使用。不使用吸血鬼的擁抱。這是推薦的傷害內建循環的替代選項，預設為停用：啟用它並停用那個，或提高它的優先順序。"
L["rm.era.priest.dps.warcrafttavern.Name"] = "傷害（Warcraft Tavern 魔杖節約）"
L["rm.era.priest.dps.warcrafttavern.Description"] = "Warcraft Tavern 減少休息時間的升級打法，作為推薦的傷害內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。單人時：以心靈震爆拉怪，施放一次暗言術:痛，只有在目標生命力高於 30% 時才再次使用心靈震爆，兩次心靈震爆之間使用魔杖，而不是懲擊或精神鞭笞。拉怪前不自動上護盾。隊伍中：暗言術:痛、心靈震爆、精神鞭笞。提醒與推薦的內建循環相同。"
L["rm.era.priest.healer.Name"] = "治療者"
L["rm.era.priest.healer.Description"] = "神聖或戒律是你的主要天賦樹時，在隊伍中選用。治療你選取的友方單位：低於 30% 時使用真言術：盾，低於 40% 時使用快速治療，驅散，隊伍中三人受傷時使用治療禱言，生命力低於一半時使用強效治療術（學會前用治療術或次級治療術），移動時或傷害輕微時使用恢復，然後以等級 3 的治療術作為高效補血。戰鬥外會對你的目標提供真言術：韌。選取敵人時提供暗言術：痛與懲擊。提醒：心靈之火、真言術：韌、神聖之靈、心靈專注、絕望禱言；注入能量預設關閉。要治療誰與降級施法由你自行處理。"
L["rm.forever.priest.dps.Name"] = "暗影與單人傷害"
L["rm.forever.priest.dps.Description"] = "適用於 1 至 60 級的暗影以及所有牧師的單人打法；永久牧師的預設循環。以真言術:盾（單人）與心靈震爆拉怪（神聖與戒律用神聖之火，學會心靈震爆前用懲擊）。接著學會後使用暗影形態，你自己的暗言術:痛與噬靈瘟疫，心靈震爆，戒律以神聖之火接懺悟，暗影形態下使用精神鞭笞；學會暗影形態前單人時，神聖意圖觸發且有三個敵人時使用神聖新星，然後是魔杖（沒有魔杖時用懲擊）。移動時：痛、瘟疫。提醒：心靈之火、真言術:韌、神聖之靈、種族增益、吸血鬼的擁抱、心靈專注、沉默、伊露恩之光；心靈尖嘯預設關閉。在永久版本中，插件看不到生命力與法力，因此用暗言術:死斬殺、治療自己與黑暗獻祭由你決定。依據 30 級測試版指南製作；暗影形態打法依循 Mobalytics。"
L["rm.forever.priest.dps.mobalytics.Name"] = "持續傷害與魔杖升級（Mobalytics）"
L["rm.forever.priest.dps.mobalytics.Description"] = "Mobalytics 的升級打法，作為推薦的暗影內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。心靈震爆與神聖之火只用於難纏的怪物（精英，或比你高兩級），你自己的暗言術:痛與噬靈瘟疫，然後是魔杖（沒有魔杖時用懲擊）。學會暗影形態後：心靈震爆、痛、瘟疫、精神鞭笞。兩次拉怪之間對自己使用真言術:盾與恢復，對自己使用祛病術。在永久版本中，插件看不到生命力與法力，因此治療自己由你決定。在多隻怪物之間擴散痛由你決定。"
L["rm.forever.priest.healer.Name"] = "戒律與神聖治療"
L["rm.forever.priest.healer.Description"] = "當戒律或神聖是你的主要天賦樹，且未學會暗影形態後的隊伍治療。治療你目前的友方目標：拉怪前使用真言術:盾、癒合禱言與恢復；驅散魔法以及驅除疾病或祛病術；癒合禱言；神聖意圖觸發時使用神聖新星；懺悟；缺少時使用恢復；治療術（在此之前為次級治療術）。目標為敵人時：暗言術:痛、神聖之火、懺悟、懲擊、魔杖。提醒：心靈之火、真言術:韌、神聖之靈、對其他玩家使用注入能量、戰鬥中的心靈專注與種族法術。在永久版本中，插件看不到生命力與法力，因此你選取的目標是判斷誰需要治療的唯一依據；緊急治療、治療禱言、束縛治療、強效治療術與快速治療、絕望禱言與黑暗獻祭由你決定。要治療誰與法術等級由你決定；學會懺悟前的戒律治療者（20–29 級）需要手動選擇它。"
L["rm.mop.priest.discipline.Name"] = "推薦"
L["rm.mop.priest.discipline.Description"] = "10 至 90 級的戒律治療，在戒律專精下選用。選取友方以治療他們：目標生命力低時、拉怪前以及約每 12 秒為了狂喜使用真言術:盾；光之澎湃觸發時使用快速治療；懺悟；目標生命力極低時使用快速治療；你們兩人都受傷時使用束縛治療；癒合禱言；三名盟友受傷時使用治療禱言與你的第六層天賦；強效治療術；移動時使用恢復；以治療術補滿。精神護罩期間會建議治療禱言或強效治療術。選取敵人以透過贖罪進行治療：懺悟、真言術:慰或神聖之火、怪群時使用你的第六層天賦、單人時使用暗言術:痛、懲擊。提醒：心靈之火、真言術:韌、五層佈道時使用大天使、心靈專注、對瀕死目標使用痛苦鎮壓、為法力使用暗影惡魔或屈心魔、注入能量、絕望禱言。由你自行處理：要治療誰、精神護罩的時機（可以開啟的提醒）、真言術:壁、虛無轉移，以及坦克身上的恩典層數。"
L["rm.mop.priest.holy.Name"] = "推薦"
L["rm.mop.priest.holy.Description"] = "10 至 90 級的神聖治療，在神聖專精下選用。選取友方以治療他們：脈輪運轉:平靜時使用聖言術:寧；只有在目標即將死亡時才使用真言術:盾；光之澎湃觸發時使用快速治療；癒合禱言；生命力極低時使用快速治療；你們兩人都受傷時使用束縛治療；隊伍中三名盟友受傷時，使用治療之環、脈輪運轉:庇護時使用聖言術:庇、你的第六層天賦與治療禱言；恢復；生命力低或兩層機緣回復時使用強效治療術；治療術。選取敵人以造成傷害：聖言術:譴、真言術:慰或神聖之火、單人時使用暗言術:痛、怪群時使用你的第六層天賦、懲擊。空的脈輪會自動替你補上（團隊中為庇護、小隊中為平靜、單人時為譴責），且絕不會切換。提醒：心靈之火、真言術:韌、對瀕死目標使用守護聖靈、五名盟友傷勢嚴重時使用神聖禮頌、為法力使用暗影惡魔或屈心魔、注入能量、絕望禱言。由你自行處理：要治療誰、聖言術:庇的擺放、光束泉與虛無轉移。"
L["rm.mop.priest.holy.icyveins.Name"] = "緊急治療最後（Icy Veins）"
L["rm.mop.priest.holy.icyveins.Description"] = "預設關閉。Icy Veins 的神聖順序，依你的脈輪而定。脈輪運轉:庇護時：三名盟友受傷時使用聖言術:庇、恢復、治療之環、癒合禱言、治療禱言，然後只有在緊急時才使用束縛治療與快速治療。其他情況：恢復、聖言術:寧、癒合禱言、強效治療術、治療術、束縛治療、快速治療、最後是真言術:盾，學會治療術之前以快速治療作為填充。切換、提醒與傷害清單與推薦的神聖內建循環相同；要使用它，請啟用它並停用推薦的循環。"
L["rm.mop.priest.shadow.Name"] = "推薦"
L["rm.mop.priest.shadow.Description"] = "10 至 90 級的暗影傷害，在暗影專精下選用。以心靈鑽刺、心靈震爆或你的持續傷害效果開場。三顆暗影寶珠時使用噬靈瘟疫（心靈震爆已就緒或還要六秒時），心靈震爆，目標生命力低於 20% 時使用暗言術:死，若你點了慰藉與瘋狂，在你的噬靈瘟疫生效期間使用精神鞭笞，對會存活的目標在接近結束時刷新暗言術:痛與吸血之觸，黑暗奔騰觸發時使用心靈鑽刺，在最佳距離使用輝環、神聖箭矢或神性之星，然後是精神鞭笞。精神鞭笞會為了心靈震爆或暗言術:死而提早中斷，或在第二次跳動後中斷；其他引導絕不中斷。移動時只建議瞬發法術。五個以上敵人時：你的第六層天賦、對你的目標施放持續傷害效果以及心靈烙印。提醒：暗影形態、心靈之火、真言術:韌、對可中斷的施法使用沉默、長時間戰鬥時使用暗影惡魔或屈心魔與注入能量、吸血鬼的擁抱、生命力低時使用絕望禱言與影散。由你自行處理：對其他目標施放持續傷害效果以及心靈烙印的落點。"
L["rm.mop.priest.shadow.warcrafttavern.Name"] = "不優先瘋狂（Warcraft Tavern）"
L["rm.mop.priest.shadow.warcrafttavern.Description"] = "預設關閉。Warcraft Tavern 的暗影順序：三顆暗影寶珠時使用噬靈瘟疫，低於 20% 時使用暗言術:死，心靈震爆，吸血之觸，暗言術:痛，黑暗奔騰觸發時使用心靈鑽刺，你的第六層天賦，精神鞭笞。與推薦的暗影內建循環不同，它絕不會在噬靈瘟疫期間提高精神鞭笞的優先順序，也不會為了心靈震爆保留噬靈瘟疫。起手、移動、怪群與提醒步驟相同；要使用它，請啟用它並停用推薦的循環。"
L["rm.mop.priest.unspecialized.Name"] = "未選擇專精"
L["rm.mop.priest.unspecialized.Description"] = "適用於 1 至 9 級，或尚未選擇專精的任何牧師。對敵人：目標會存活夠久時使用暗言術:痛，然後是懲擊。對友方：目標生命力低時使用快速治療，否則使用真言術:盾。提醒：心靈之火，以及單人受傷時對自己施放護盾。10 級選擇專精後會切換為該專精自己的內建循環。"
L["rm.retail.priest.discipline.Name"] = "贖罪（Icy Veins）"
L["rm.retail.priest.discipline.Description"] = "至暗之夜的戒律專精，僅供參考：暴雪的戰鬥助手不涵蓋治療者，遊戲在戰鬥中會隱藏所有人的生命力，而 Rotation Master 選擇的是法術而不是目標，因此它會打出透過贖罪轉化為治療的傷害，決定要治療誰則交給你。友方目標：真言術:盾（虛無之盾），懺悟，快速治療。敵人：12 秒內未施放過暗言術:痛時使用暗言術:痛，心靈震爆，懺悟，真言術:盾，暗言術:死，虛無衝擊，懲擊。戰鬥中的提醒：真言術:輝、佈道、終極懺罪、對友方目標使用痛苦鎮壓；兩波拉怪之間的真言術:韌。絕望禱言由你決定。大量傷害來臨前為團隊預鋪贖罪的時機由你自行掌握。"
L["rm.retail.priest.discipline.wowhead.Name"] = "暗言術：死優先參考（Wowhead）"
L["rm.retail.priest.discipline.wowhead.Description"] = "僅供參考，預設關閉：Wowhead 的第 1 季神諭者施放順序，透過讀取減益效果來維持暗言術：痛，而至暗之夜會在戰鬥中隱藏該減益效果。暗言術：痛，暗言術：死冷卻結束就使用，懺悟，心靈震爆，懲擊；友方目標時優先使用懺悟。提醒與 Icy Veins 內建循環相同。"
L["rm.retail.priest.holy.Name"] = "Icy Veins"
L["rm.retail.priest.holy.Description"] = "至暗之夜的神聖專精，僅供參考：遊戲在戰鬥中會隱藏所有人的生命力，而 Rotation Master 選擇的是法術而不是目標，因此它會針對你目前的目標讓聖言術、癒合禱言與觸發效果持續運轉，治療分配則交給你。友方目標：聖言術:庇，聖言術:寧，癒合禱言，光之澎湃觸發時使用治療禱言，祈福，織光師觸發時使用治療禱言，光之澎湃觸發時使用快速治療，在隊伍中使用治療禱言，移動中使用神聖新星，快速治療。敵人：聖言術:譴，神聖之火，移動中使用神聖新星，懲擊。提醒：戰鬥中的神化、神聖禮頌與輝環、對友方目標使用守護聖靈（正式版中生命力是隱藏的，因此對方是否瀕死由你決定）、真言術:韌。絕望禱言由你自行處理。"
L["rm.retail.priest.initial.Name"] = "暴雪戰鬥助手"
L["rm.retail.priest.initial.Description"] = "在你選擇專精之前推薦使用（此時遊戲回報的是牧師的初始專精）。醒目提示暴雪戰鬥助手建議的下一個法術，這是在至暗之夜的戰鬥中，遊戲仍允許插件讀取的唯一循環建議；你施法或引導時它會等待。同時附上每個牧師內建循環共用的提醒，各項在你學會對應法術後才會出現。當你在 10 級選擇專精後，該專精的內建循環會接手。"
L["rm.retail.priest.shadow.Name"] = "暴雪戰鬥助手"
L["rm.retail.priest.shadow.Description"] = "推薦至暗之夜的暗影專精使用。在戰鬥中，遊戲現在會對插件隱藏你的持續傷害效果、增益效果、冷卻時間與生命力，因此它會顯示暴雪自己的戰鬥助手建議（一鍵循環，它會維持你的持續傷害效果、暗影形態與虛無形態，並讓精神鞭笞引導完畢），並在你施法或沒有選取敵人時停止。提醒它未包含的內容：施放虛無形態後的 20 秒內使用注入能量、兩波拉怪之間的暗影形態與真言術:韌、對可中斷的施法使用沉默（只會在遊戲允許讀取該施法的場合亮起）。正式版中生命力是隱藏的，因此絕望禱言由你決定。"
L["rm.retail.priest.shadow.icyveins.Name"] = "參考（Icy Veins）"
L["rm.retail.priest.shadow.icyveins.Description"] = "僅供參考，預設關閉：Icy Veins 與 SimulationCraft 的施放順序需要讀取持續傷害效果的計時、暗言術:瘋與虛無形態，而至暗之夜會在戰鬥中隱藏它們；正式版中瘋狂值與生命力是隱藏的，因此瘋狂值達上限時的暗言術:瘋、暗言術:死的斬殺階段與絕望禱言由你自行處理。拉怪前使用吸血之觸；以觸手猛擊施加吸血之觸；吸血之觸與暗言術:痛在剩餘最後 30% 時刷新；暗言術:瘋即將結束或在虛無形態期間時使用暗言術:瘋；瘋狂效果期間使用虛無衝擊；兩層充能時使用觸手猛擊；虛無洪流；心靈震爆；觸手猛擊；瘋狂效果期間使用精神鞭笞:瘋狂；虛無箭雨；移動中使用暗言術:死與暗言術:痛；精神鞭笞，心靈震爆就緒時中斷引導。提醒：輝環、兩個持續傷害效果都生效時使用虛無形態、虛無形態期間使用注入能量。"
L["rm.sod.priest.dps.Name"] = "傷害（探索賽季）"
L["rm.sod.priest.dps.Description"] = "探索賽季伺服器上的傷害輸出，適用於 1 至 60 級，使用你已紋刻的符文。暗影形態；以吸血之觸或心靈震爆拉怪（暗影形態之前用懺悟、神聖之火或懲擊）。維持虛無瘟疫、暗言術:痛與吸血之觸（只有未紋刻痛苦與折磨時才在接近結束時刷新），心靈震爆冷卻結束即使用，熔解臉龐時使用精神鞭笞，生命力高於一半時使用暗言術:死，然後以心靈鑽刺作為填充，若有第 8 階段六件套裝則改用精神鞭笞。四個以上敵人時使用虛無區域與心靈烙印。單人時對瀕死目標使用魔杖。提醒：心靈之火、真言術:韌、魔胎、暗影惡魔、虛無之眼與影散、心靈專注、心靈尖嘯、漸隱術、絕望禱言。"
L["rm.sod.priest.dps.wowhead.Name"] = "傷害（探索賽季，Wowhead 心靈鑽刺疊層）"
L["rm.sod.priest.dps.wowhead.Description"] = "Wowhead 與 Warcraft Tavern 的探索賽季打法，作為推薦的探索賽季傷害內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。心靈震爆會等待目標身上有三層你的心靈鑽刺（在你紋刻心靈鑽刺之前正常施放），精神鞭笞只在熔解臉龐時使用，心靈鑽刺作為填充。其餘與推薦的內建循環相同。"
L["rm.sod.priest.healer.Name"] = "治療（探索賽季）"
L["rm.sod.priest.healer.Description"] = "在探索賽季伺服器上，神聖或戒律是你的主要天賦樹時，在隊伍中選用；依據 Icy Veins。治療你選取的友方單位：拉怪前以及就緒時使用癒合禱言，生命力低於一半時使用真言術：盾，懺悟，光之澎湃觸發時使用瞬發快速治療，緊急時使用快速治療，驅散，隊伍中三人受傷時使用治療之環與治療禱言，生命力低於一半時使用強效治療術，移動時或傷害輕微時使用恢復，然後使用治療術。選取敵人時提供暗言術：痛、虛無瘟疫、懺悟、神聖之火與懲擊。提醒包括暗影惡魔、對瀕死目標使用痛苦鎮壓、隊伍受傷時使用真言術：壁與救星之靈。"
L["rm.sod.priest.healer.warcrafttavern.Name"] = "治療（探索賽季，Warcraft Tavern）"
L["rm.sod.priest.healer.warcrafttavern.Description"] = "Warcraft Tavern 的機緣回復循環，專為機緣回復與靈魂結界設計，作為推薦的探索賽季治療者內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。癒合禱言冷卻結束即使用，只要你的目標可以接受就施放真言術:盾（已紋刻靈魂結界時；否則在生命力低於一半時），承受大量傷害時使用懺悟，三人受傷時使用治療之環，三層機緣回復時使用強效治療術或治療禱言，輕微傷害時使用恢復，並對輕傷使用快速治療來累積層數（已紋刻機緣回復時；否則在低於 30% 時）。"
L["rm.tbc.priest.dps.icyveins.Name"] = "傷害（Icy Veins）"
L["rm.tbc.priest.dps.icyveins.Description"] = "1 至 70 級的傷害輸出，只要治療內建循環不適用就會使用。前期使用懲擊與魔杖，接著隨著學會依序加入心靈震爆、暗言術:痛、精神鞭笞、暗影形態、吸血之觸與暗言術:死；心靈震爆之前先上持續傷害效果；單人時對瀕死目標使用魔杖。神聖與戒律的解任務玩家使用神聖之火與懲擊。提醒：心靈之火、真言術:韌、種族增益、心靈專注、暗影惡魔。精神鞭笞過了第一次跳動後，若心靈震爆已就緒（或生命力高於一半時暗言術:死已就緒），就會被提早中斷。護盾與治療由你自行處理。"
L["rm.tbc.priest.dps.wowhead.Name"] = "傷害（Wowhead）"
L["rm.tbc.priest.dps.wowhead.Description"] = "依據 Wowhead 指南的傷害輸出，作為推薦的 Icy Veins 傷害內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。以心靈震爆開怪，並優先於刷新持續傷害效果，只在生命力下降時使用吸血鬼的擁抱，對瀕死目標使用法術而非魔杖。其餘與推薦的內建循環相同。"
L["rm.tbc.priest.healer.icyveins.Name"] = "治療（Icy Veins）"
L["rm.tbc.priest.healer.icyveins.Description"] = "依據 Icy Veins 順序的治療：真言術:盾、驅散、束縛治療、恢復、快速治療、強效治療術（任意等級）、群體治療，最後是癒合禱言。要治療誰由你決定。這是推薦的 Wowhead 治療內建循環的替代選項，預設為停用：啟用它並停用那個，或提高它的優先順序。"
L["rm.tbc.priest.healer.wowhead.Name"] = "治療（Wowhead）"
L["rm.tbc.priest.healer.wowhead.Description"] = "神聖或戒律是你的主要天賦樹時的隊伍治療。它針對你選取的友方單位提供建議；要治療誰由你決定。拉怪前以及就緒時使用癒合禱言、恢復、緊急時使用真言術:盾、驅散、隊伍受傷時使用治療之環或治療禱言、束縛治療、快速治療與強效治療術，並以等級 1 的強效治療術作為低耗補血。選取敵人時會提供少量傷害技能。"
